class GlobiquestVoicePreferences{
 constructor(){this.preferences={};try{const stored=JSON.parse(localStorage.getItem('globiquest-voices')||'{}');this.preferences=stored&&typeof stored==='object'&&!Array.isArray(stored)?stored:{}}catch{}this.hindiNeedsAlternative=false;try{if(localStorage.getItem('globiquest.hindi-voice.v4')!=='1'){delete this.preferences['hi-IN'];localStorage.setItem('globiquest-voices',JSON.stringify(this.preferences));localStorage.setItem('globiquest.hindi-voice.v4','1')}}catch{}this.rate=.78;this.volume=.72;this.pitch=.98;try{if(localStorage.getItem('globiquest.hindi-voice.v2')!=='1'){delete this.preferences['hi-IN'];localStorage.setItem('globiquest-voices',JSON.stringify(this.preferences));localStorage.setItem('globiquest.hindi-voice.v2','1')}}catch{}}
 available(language){const voices=window.speechSynthesis?.getVoices()||[];return voices.filter(v=>v.lang.toLowerCase().split('-')[0]===language.toLowerCase().split('-')[0]).sort((a,b)=>this.score(b,language)-this.score(a,language))}
 score(voice,language){let score=voice.lang.toLowerCase()===language.toLowerCase()?15:0;if(/natural|neural|enhanced|premium/i.test(voice.name))score+=80;if(/samantha|serena|sonia|aria|jenny|kyoko|amelie|amélie|paulina|monica|mónica|swara|haruka/i.test(voice.name))score+=30;if(language.toLowerCase().startsWith('hi')&&/swara|heera|aditi|lekha/i.test(voice.name))score+=100;if(language.toLowerCase().startsWith('hi')&&/google|swara|natural|neural/i.test(voice.name))score+=180;if(voice.localService)score+=2;return score}
 settings(language){return language.toLowerCase().startsWith('hi')?{rate:.9,pitch:1,volume:.7}:{rate:this.rate,pitch:this.pitch,volume:this.volume}}
 selected(language){const list=this.available(language);return list.find(v=>v.voiceURI===this.preferences[language])||list[0]}
 cycle(language){const list=this.available(language);if(list.length<2)return null;const current=this.selected(language);const next=list[(list.findIndex(v=>v.voiceURI===current.voiceURI)+1)%list.length];this.preferences[language]=next.voiceURI;try{localStorage.setItem('globiquest-voices',JSON.stringify(this.preferences))}catch{}return next}
}
window.GlobiquestVoicePreferences=GlobiquestVoicePreferences;
/* Own each speech request so cancellation never becomes a false failure alert. */
class GlobiquestSpeechPlayer{
 constructor(){this.synth=window.speechSynthesis;this.sequence=0;this.active=null;this.callbacks=null;this.startTimer=null;this.waitCleanup=null}
 stop(){++this.sequence;clearTimeout(this.startTimer);this.waitCleanup?.();this.waitCleanup=null;this.synth?.cancel();this.active=null;this.callbacks?.stop?.();this.callbacks=null}
 speak(text,language,prefs,callbacks={}){this.stop();const token=++this.sequence;this.callbacks=callbacks;callbacks.stop?.();if(!this.synth||!window.SpeechSynthesisUtterance){callbacks.error?.('unsupported');return}let voices=prefs.available(language);const selected=prefs.selected(language),alternate=voices.filter(v=>v!==selected).sort((a,b)=>Number(b.localService)-Number(a.localService))[0],candidates=[selected,alternate,null].filter((v,i,a)=>a.indexOf(v)===i&&v!==undefined);let index=0,waiting=false;
  const attempt=()=>{if(token!==this.sequence)return;clearTimeout(this.startTimer);const voice=candidates[index++],u=new window.SpeechSynthesisUtterance(text);this.active=u;u.lang=language;if(voice)u.voice=voice;const settings=prefs.settings?.(language)||prefs;u.rate=settings.rate;u.pitch=settings.pitch;u.volume=settings.volume;
   u.onstart=()=>{if(token!==this.sequence)return;clearTimeout(this.startTimer);callbacks.start?.()};u.onend=()=>{if(token!==this.sequence)return;clearTimeout(this.startTimer);this.active=null;this.callbacks=null;callbacks.stop?.();callbacks.end?.()};
   u.onerror=e=>{if(token!==this.sequence)return;clearTimeout(this.startTimer);this.active=null;callbacks.stop?.();const error=e.error||'synthesis-failed';if(error==='canceled'||error==='interrupted'){this.callbacks=null;return}if(error==='not-allowed'||error==='audio-hardware'||error==='language-unavailable'){callbacks.error?.(error);return}if(index<Math.min(candidates.length,3)){attempt();return}if(!voices.length&&!waiting){waiting=true;let timer;const ready=()=>{this.waitCleanup?.();this.waitCleanup=null;if(token!==this.sequence)return;voices=prefs.available(language);const fallback=voices.find(v=>v.localService)||voices[0];if(fallback){candidates.push(fallback);index=candidates.length-1;attempt()}else callbacks.error?.(error)};this.waitCleanup=()=>{clearTimeout(timer);this.synth.removeEventListener?.('voiceschanged',ready)};this.synth.addEventListener?.('voiceschanged',ready);timer=setTimeout(ready,1000);return}callbacks.error?.(error)};
   this.startTimer=setTimeout(()=>{if(token!==this.sequence||this.active!==u)return;++this.sequence;this.active=null;this.callbacks=null;this.synth.cancel();callbacks.stop?.();callbacks.error?.('start-timeout')},4500);
   try{this.synth.resume?.();this.synth.speak(u)}catch{u.onerror({error:'synthesis-unavailable'})}
  };attempt()
 }
}
window.GlobiquestSpeechPlayer=GlobiquestSpeechPlayer;
